using ArchInsight.Infrastructure;
using Microsoft.EntityFrameworkCore;

namespace ArchInsight.Api;

public static class Phase6SchemaUpgrade
{
    public static async Task ApplyAsync(AssessmentDbContext db)
    {
        if (db.Database.ProviderName?.Contains("Sqlite", StringComparison.OrdinalIgnoreCase) == true)
            await db.Database.ExecuteSqlRawAsync(SqliteSchema);
        else if (db.Database.ProviderName?.Contains("SqlServer", StringComparison.OrdinalIgnoreCase) == true)
            await db.Database.ExecuteSqlRawAsync(SqlServerSchema);
    }

    private const string SqliteSchema = """
        CREATE TABLE IF NOT EXISTS ArchitectureSnapshots (Id TEXT NOT NULL CONSTRAINT PK_ArchitectureSnapshots PRIMARY KEY, RepositoryAnalysisId TEXT NOT NULL, CreatedDate TEXT NOT NULL, Hash TEXT NOT NULL, ApplicationCount INTEGER NOT NULL, ServiceCount INTEGER NOT NULL, DependencyCount INTEGER NOT NULL, FrameworkInventoryJson TEXT NOT NULL, TechnologyInventoryJson TEXT NOT NULL, SummaryJson TEXT NOT NULL, RiskScore INTEGER NOT NULL, ModernizationScore INTEGER NOT NULL, TechnicalDebt INTEGER NOT NULL, CloudReadiness INTEGER NOT NULL, SecurityScore INTEGER NOT NULL, ConsistencyScore INTEGER NOT NULL, MaturityIndex INTEGER NOT NULL, CONSTRAINT FK_ArchitectureSnapshots_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        CREATE TABLE IF NOT EXISTS DriftAlerts (Id TEXT NOT NULL CONSTRAINT PK_DriftAlerts PRIMARY KEY, RepositoryAnalysisId TEXT NOT NULL, PreviousSnapshotId TEXT NULL, CurrentSnapshotId TEXT NOT NULL, CreatedDate TEXT NOT NULL, Category TEXT NOT NULL, Severity TEXT NOT NULL, Title TEXT NOT NULL, Description TEXT NOT NULL, AffectedAsset TEXT NOT NULL, Status TEXT NOT NULL, CONSTRAINT FK_DriftAlerts_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        CREATE TABLE IF NOT EXISTS ArchitecturePolicies (Id TEXT NOT NULL CONSTRAINT PK_ArchitecturePolicies PRIMARY KEY, Name TEXT NOT NULL, Description TEXT NOT NULL, Category TEXT NOT NULL, RuleType TEXT NOT NULL, Severity TEXT NOT NULL, Enabled INTEGER NOT NULL, CreatedDate TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS PolicyEvaluations (Id TEXT NOT NULL CONSTRAINT PK_PolicyEvaluations PRIMARY KEY, ArchitectureSnapshotId TEXT NOT NULL, ArchitecturePolicyId TEXT NOT NULL, EvaluatedAt TEXT NOT NULL, Asset TEXT NOT NULL, Status TEXT NOT NULL, Evidence TEXT NOT NULL, CONSTRAINT FK_PolicyEvaluations_ArchitectureSnapshots_ArchitectureSnapshotId FOREIGN KEY (ArchitectureSnapshotId) REFERENCES ArchitectureSnapshots(Id) ON DELETE CASCADE, CONSTRAINT FK_PolicyEvaluations_ArchitecturePolicies_ArchitecturePolicyId FOREIGN KEY (ArchitecturePolicyId) REFERENCES ArchitecturePolicies(Id) ON DELETE CASCADE);
        CREATE TABLE IF NOT EXISTS TechnologyStandards (Id TEXT NOT NULL CONSTRAINT PK_TechnologyStandards PRIMARY KEY, Technology TEXT NOT NULL, VersionPattern TEXT NOT NULL, Lifecycle TEXT NOT NULL, Rationale TEXT NOT NULL, ReviewDate TEXT NULL);
        CREATE TABLE IF NOT EXISTS ArchitectureDecisions (Id TEXT NOT NULL CONSTRAINT PK_ArchitectureDecisions PRIMARY KEY, RepositoryAnalysisId TEXT NOT NULL, Title TEXT NOT NULL, Context TEXT NOT NULL, Decision TEXT NOT NULL, Consequences TEXT NOT NULL, Status TEXT NOT NULL, CreatedDate TEXT NOT NULL, CONSTRAINT FK_ArchitectureDecisions_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        CREATE TABLE IF NOT EXISTS PullRequestReviews (Id TEXT NOT NULL CONSTRAINT PK_PullRequestReviews PRIMARY KEY, RepositoryAnalysisId TEXT NOT NULL, PullRequestNumber INTEGER NOT NULL, Title TEXT NOT NULL, HeadRevision TEXT NOT NULL, DiffHash TEXT NOT NULL, RiskScore INTEGER NOT NULL, RiskLevel TEXT NOT NULL, Summary TEXT NOT NULL, FindingsJson TEXT NOT NULL, ReviewedAt TEXT NOT NULL, CONSTRAINT FK_PullRequestReviews_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        CREATE INDEX IF NOT EXISTS IX_ArchitectureSnapshots_RepositoryAnalysisId_CreatedDate ON ArchitectureSnapshots(RepositoryAnalysisId,CreatedDate);
        CREATE INDEX IF NOT EXISTS IX_DriftAlerts_RepositoryAnalysisId_Status_CreatedDate ON DriftAlerts(RepositoryAnalysisId,Status,CreatedDate);
        CREATE UNIQUE INDEX IF NOT EXISTS IX_ArchitecturePolicies_Name ON ArchitecturePolicies(Name);
        CREATE UNIQUE INDEX IF NOT EXISTS IX_PolicyEvaluations_ArchitectureSnapshotId_ArchitecturePolicyId_Asset ON PolicyEvaluations(ArchitectureSnapshotId,ArchitecturePolicyId,Asset);
        CREATE UNIQUE INDEX IF NOT EXISTS IX_TechnologyStandards_Technology_VersionPattern ON TechnologyStandards(Technology,VersionPattern);
        CREATE INDEX IF NOT EXISTS IX_PullRequestReviews_RepositoryAnalysisId_PullRequestNumber_HeadRevision ON PullRequestReviews(RepositoryAnalysisId,PullRequestNumber,HeadRevision);
        """;

    private const string SqlServerSchema = """
        IF OBJECT_ID(N'ArchitectureSnapshots',N'U') IS NULL CREATE TABLE ArchitectureSnapshots (Id uniqueidentifier NOT NULL CONSTRAINT PK_ArchitectureSnapshots PRIMARY KEY, RepositoryAnalysisId uniqueidentifier NOT NULL, CreatedDate datetimeoffset NOT NULL, Hash nvarchar(64) NOT NULL, ApplicationCount int NOT NULL, ServiceCount int NOT NULL, DependencyCount int NOT NULL, FrameworkInventoryJson nvarchar(max) NOT NULL, TechnologyInventoryJson nvarchar(max) NOT NULL, SummaryJson nvarchar(max) NOT NULL, RiskScore int NOT NULL, ModernizationScore int NOT NULL, TechnicalDebt int NOT NULL, CloudReadiness int NOT NULL, SecurityScore int NOT NULL, ConsistencyScore int NOT NULL, MaturityIndex int NOT NULL, CONSTRAINT FK_ArchitectureSnapshots_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        IF OBJECT_ID(N'DriftAlerts',N'U') IS NULL CREATE TABLE DriftAlerts (Id uniqueidentifier NOT NULL CONSTRAINT PK_DriftAlerts PRIMARY KEY, RepositoryAnalysisId uniqueidentifier NOT NULL, PreviousSnapshotId uniqueidentifier NULL, CurrentSnapshotId uniqueidentifier NOT NULL, CreatedDate datetimeoffset NOT NULL, Category nvarchar(80) NOT NULL, Severity nvarchar(20) NOT NULL, Title nvarchar(300) NOT NULL, Description nvarchar(max) NOT NULL, AffectedAsset nvarchar(500) NOT NULL, Status nvarchar(30) NOT NULL, CONSTRAINT FK_DriftAlerts_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        IF OBJECT_ID(N'ArchitecturePolicies',N'U') IS NULL CREATE TABLE ArchitecturePolicies (Id uniqueidentifier NOT NULL CONSTRAINT PK_ArchitecturePolicies PRIMARY KEY, Name nvarchar(200) NOT NULL, Description nvarchar(max) NOT NULL, Category nvarchar(80) NOT NULL, RuleType nvarchar(80) NOT NULL, Severity nvarchar(20) NOT NULL, Enabled bit NOT NULL, CreatedDate datetimeoffset NOT NULL);
        IF OBJECT_ID(N'PolicyEvaluations',N'U') IS NULL CREATE TABLE PolicyEvaluations (Id uniqueidentifier NOT NULL CONSTRAINT PK_PolicyEvaluations PRIMARY KEY, ArchitectureSnapshotId uniqueidentifier NOT NULL, ArchitecturePolicyId uniqueidentifier NOT NULL, EvaluatedAt datetimeoffset NOT NULL, Asset nvarchar(500) NOT NULL, Status nvarchar(20) NOT NULL, Evidence nvarchar(max) NOT NULL, CONSTRAINT FK_PolicyEvaluations_ArchitectureSnapshots_ArchitectureSnapshotId FOREIGN KEY (ArchitectureSnapshotId) REFERENCES ArchitectureSnapshots(Id) ON DELETE CASCADE, CONSTRAINT FK_PolicyEvaluations_ArchitecturePolicies_ArchitecturePolicyId FOREIGN KEY (ArchitecturePolicyId) REFERENCES ArchitecturePolicies(Id) ON DELETE CASCADE);
        IF OBJECT_ID(N'TechnologyStandards',N'U') IS NULL CREATE TABLE TechnologyStandards (Id uniqueidentifier NOT NULL CONSTRAINT PK_TechnologyStandards PRIMARY KEY, Technology nvarchar(160) NOT NULL, VersionPattern nvarchar(80) NOT NULL, Lifecycle nvarchar(30) NOT NULL, Rationale nvarchar(max) NOT NULL, ReviewDate datetimeoffset NULL);
        IF OBJECT_ID(N'ArchitectureDecisions',N'U') IS NULL CREATE TABLE ArchitectureDecisions (Id uniqueidentifier NOT NULL CONSTRAINT PK_ArchitectureDecisions PRIMARY KEY, RepositoryAnalysisId uniqueidentifier NOT NULL, Title nvarchar(300) NOT NULL, Context nvarchar(max) NOT NULL, Decision nvarchar(max) NOT NULL, Consequences nvarchar(max) NOT NULL, Status nvarchar(30) NOT NULL, CreatedDate datetimeoffset NOT NULL, CONSTRAINT FK_ArchitectureDecisions_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        IF OBJECT_ID(N'PullRequestReviews',N'U') IS NULL CREATE TABLE PullRequestReviews (Id uniqueidentifier NOT NULL CONSTRAINT PK_PullRequestReviews PRIMARY KEY, RepositoryAnalysisId uniqueidentifier NOT NULL, PullRequestNumber int NOT NULL, Title nvarchar(300) NOT NULL, HeadRevision nvarchar(120) NOT NULL, DiffHash nvarchar(64) NOT NULL, RiskScore int NOT NULL, RiskLevel nvarchar(20) NOT NULL, Summary nvarchar(max) NOT NULL, FindingsJson nvarchar(max) NOT NULL, ReviewedAt datetimeoffset NOT NULL, CONSTRAINT FK_PullRequestReviews_RepositoryAnalyses_RepositoryAnalysisId FOREIGN KEY (RepositoryAnalysisId) REFERENCES RepositoryAnalyses(Id) ON DELETE CASCADE);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_ArchitectureSnapshots_RepositoryAnalysisId_CreatedDate') CREATE INDEX IX_ArchitectureSnapshots_RepositoryAnalysisId_CreatedDate ON ArchitectureSnapshots(RepositoryAnalysisId,CreatedDate);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_DriftAlerts_RepositoryAnalysisId_Status_CreatedDate') CREATE INDEX IX_DriftAlerts_RepositoryAnalysisId_Status_CreatedDate ON DriftAlerts(RepositoryAnalysisId,Status,CreatedDate);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_ArchitecturePolicies_Name') CREATE UNIQUE INDEX IX_ArchitecturePolicies_Name ON ArchitecturePolicies(Name);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_PolicyEvaluations_ArchitectureSnapshotId_ArchitecturePolicyId_Asset') CREATE UNIQUE INDEX IX_PolicyEvaluations_ArchitectureSnapshotId_ArchitecturePolicyId_Asset ON PolicyEvaluations(ArchitectureSnapshotId,ArchitecturePolicyId,Asset);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_TechnologyStandards_Technology_VersionPattern') CREATE UNIQUE INDEX IX_TechnologyStandards_Technology_VersionPattern ON TechnologyStandards(Technology,VersionPattern);
        IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name=N'IX_PullRequestReviews_RepositoryAnalysisId_PullRequestNumber_HeadRevision') CREATE INDEX IX_PullRequestReviews_RepositoryAnalysisId_PullRequestNumber_HeadRevision ON PullRequestReviews(RepositoryAnalysisId,PullRequestNumber,HeadRevision);
        """;
}
